function pipe() {
  var fns = Array.prototype.slice.call(arguments);
  return function (value) {
    var out = value;
    for (var i = 0; i < fns.length; i++) {
      out = fns[i](out);
    }
    return out;
  };
}

function compose() {
  var fns = Array.prototype.slice.call(arguments);
  return function (value) {
    var out = value;
    for (var i = fns.length - 1; i >= 0; i--) {
      out = fns[i](out);
    }
    return out;
  };
}

