function countChecksSlow(list) {
  var checks = 0;
  for (var i = 0; i < list.length; i++) {
    for (var j = i + 1; j < list.length; j++) {
      checks = checks + 1;
      if (list[i] === list[j]) return checks;
    }
  }
  return checks;
}

function countChecksFast(list) {
  var seen = new Set();
  var checks = 0;
  for (var i = 0; i < list.length; i++) {
    checks = checks + 1;
    if (seen.has(list[i])) return checks;
    seen.add(list[i]);
